<script lang="ts">
import{onMount}from'svelte';import BeeAvatar from '$lib/components/BeeAvatar.svelte';import{beeCatalog}from'$lib/hive';
let snapshot:any=$state(null),error=$state(''),busy=$state(false),selected=$state('drift'),view=$state('decisions');const colors=['#e8b74c','#a78bfa','#f472b6'];const money=(n:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n??0);const time=(n:number)=>n?new Date(n).toLocaleTimeString():'No record';const rows=()=>Object.entries(snapshot?.paper??{}).map(([id,a]:[string,any])=>({id,...a,bee:id.split(':')[0],symbol:id.split(':')[1]})).sort((a,b)=>b.equity-a.equity);const account=(bee:string)=>rows().find(a=>a.bee===bee);const active=()=>account(selected);const stale=(a:any)=>!a?.lastDecision?.at||Date.now()-a.lastDecision.at>900000;const total=(field:string)=>rows().reduce((s,a)=>s+(a[field]||0),0);
async function refresh(){if(busy)return;busy=true;try{const r=await fetch('/api/hive');if(!r.ok)throw Error('Hive evidence is temporarily unavailable');snapshot=await r.json();error='';}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;}}
function points(history:any[]){if(!history?.length)return '';const values=history.map(h=>h.equity),lo=Math.min(...values),hi=Math.max(...values),span=Math.max(hi-lo,1);return history.map((h,i)=>`${12+i*276/Math.max(1,history.length-1)},${148-(h.equity-lo)*116/span}`).join(' ');}
onMount(()=>{void refresh();const t=setInterval(()=>{if(!document.hidden)void refresh();},60000);return()=>clearInterval(t);});
</script>
<svelte:head><title>The live hive · OmieBot AI Trading</title><meta name="description" content="Follow OmieBot Bees, recorded paper decisions, positions, equity history and research evidence."/></svelte:head>
<main><header><a class="brand" href="/">Omie<span>Bot</span><small>THE LIVE HIVE</small></a><nav><a href="/">Terminal</a><a href="/invest">Trading capital</a><a href="/admin">Operations ↗</a></nav><span class="mode"><i></i> REAL MARKETS · PAPER CAPITAL</span></header><div class="heading"><div><span class="eyebrow">INDEPENDENT MINDS. SHARED DISCIPLINE.</span><h1>Watch the hive at work<span>.</span></h1><p>Every decision has a record. Every Bee has boundaries.</p></div><button onclick={refresh} disabled={busy}>{busy?'Refreshing…':'Refresh evidence ↻'}</button></div>{#if snapshot?.lastCycle?.outcomes?.some((o:any)=>o.status!==200)}<aside role="alert">Latest cycle could not evaluate every feed. {snapshot.lastCycle.outcomes.filter((o:any)=>o.status!==200).map((o:any)=>o.symbol+': '+(o.reason??o.error??'unavailable')).join('; ')}. Account cards show their last recorded decision.</aside>{/if}{#if error}<aside role="alert">{error}. Previously loaded values may be stale.</aside>{/if}<div class="metrics"><section><small>HIVE PAPER EQUITY</small><strong>{snapshot?money(total('equity')):'—'}</strong><span>{rows().length} recorded accounts</span></section><section><small>NET PAPER P&L</small><strong class:negative={total('pnl')<0}>{snapshot?money(total('pnl')):'—'}</strong><span>Includes recorded simulation costs</span></section><section><small>SIMULATED FEES</small><strong>{snapshot?money(total('fees')):'—'}</strong><span>Accumulated since fee tracking began</span></section><section><small>LAST EVALUATION</small><strong class="smaller">{time(snapshot?.lastCycle?.at?Date.parse(snapshot.lastCycle.at):0)}</strong><span>{snapshot?.paused?'Hive paused':'5 minute market cycle'} · view refresh 60s</span></section></div><div class="workspace"><div class="bee-grid">{#each beeCatalog.slice(0,3) as bee,i}{@const a=account(bee.id)}<article class="bee-card" style={`--bee:${colors[i]}`}><div class="bee-head"><BeeAvatar color={colors[i]} size={54}/><div><h2>{bee.name} Bee</h2><p>{bee.role}</p></div><span class="rank">{a?'#'+(rows().findIndex(r=>r.bee===bee.id)+1):'—'}</span></div><strong class="equity">{a?money(a.equity):'Awaiting cycle'}</strong><p class:negative={(a?.pnl??0)<0} class="return">{a?money(a.pnl)+' net paper P&L':'No recorded account yet'}</p><div class="state" class:benched={(a?.dayTrades??0)>=4}><strong>{snapshot?.paused?'PAUSED':stale(a)?'FEED STALE · ABSTAIN':(a?.dayTrades??0)>=4?'ENTRY CAP REACHED':a?.quantity>0?'POSITION OPEN':'OBSERVING'}</strong><span>{a?.lastDecision?.reason??'Waiting for the first recorded decision'}</span></div><div class="position"><strong>{a?.quantity>0?'LONG':'FLAT'} {a?.symbol??'BTC-USDT'}</strong><span>{a?.quantity>0?money(a.quantity*a.mark):'In simulated cash'}</span>{#if a?.quantity>0}<small>Entry {money(a.entry)} · mark {money(a.mark)} · stop {money(a.entry*.98)}</small>{/if}</div><div class="chart"><div class="chart-title"><span>RECORDED EQUITY</span><span>{a?.history?.length??0} observations</span></div>{#if a?.history?.length}<svg viewBox="0 0 300 180" role="img" aria-label={`${bee.name} recorded paper equity`}><path d="M12 32H288M12 90H288M12 148H288" stroke="#ffffff0c"/><polyline points={points(a.history.length===1?[a.history[0],a.history[0]]:a.history)} fill="none" stroke={colors[i]} stroke-width="2.5" vector-effect="non-scaling-stroke"/></svg><div class="axis"><span>{time(a.history[0].at)}</span><span>{time(a.history.at(-1).at)}</span></div>{:else}<div class="no-chart">History starts with the next recorded cycle.<br/>No backfilled performance.</div>{/if}</div><div class="call"><small>LAST CALL · {time(a?.lastDecision?.at)}</small><h3>{a?.lastDecision?.action?.toUpperCase()??'AWAITING EVIDENCE'}</h3><p>{a?.lastDecision?.model??bee.model}</p><span>{a?.lastDecision?.reason??'The Bee will abstain without eligible data.'}</span></div><div class="limits"><span>Entries / exits today <b>{a?.dayTrades??0} · 4 entry cap</b></span><progress max="4" value={Math.min(a?.dayTrades??0,4)} aria-label={`${bee.name} daily activity`}></progress><span>Protective exits remain available after the entry cap.</span></div><footer><span>FEES <b>{money(a?.fees)}</b></span><span>FILLS <b>{a?.trades??0}</b></span><button onclick={()=>{selected=bee.id;view='decisions';document.getElementById('evidence')?.scrollIntoView({behavior:'smooth'});}}>Inspect Bee ↗</button></footer></article>{/each}</div><aside class="side"><section class="flow"><div class="panel-title"><span>DECISION ENGINE</span><span>5m cycle</span></div><h2>Code has the final say.</h2><div class="flow-grid"><div class="core">✦<small>Risk<br/>gate</small></div><div>{#each beeCatalog.slice(0,3) as bee,i}<button style={`--bee:${colors[i]}`} onclick={()=>selected=bee.id}><BeeAvatar color={colors[i]} size={30}/><span><b>{bee.name}</b><small>{account(bee.id)?.lastDecision?.action??'awaiting cycle'}</small></span><span class="dot"></span></button>{/each}</div></div><p>Closed-bar signals → deterministic limits → simulated fills</p><small>Laya installed locally · shadow adapter · production inference not connected</small></section><section class="keeper"><span class="eyebrow">THE BEEKEEPER</span><h2>Study. Challenge. Validate.</h2><p>Daily retained-data evaluation at <b>04:00 Nigeria time</b>. Candidates stay in shadow until improvement and forward-paper checks pass.</p><a href="/admin">Read training reports & manage the hive →</a><small>No paid model requests from daily training. Laya weight fine-tuning is separate and pending.</small></section><section><div class="panel-title"><span>HIVE LEADERBOARD</span><span>Paper only</span></div>{#each rows() as a,i}<button class="leader" onclick={()=>selected=a.bee}><span>{i+1}</span><b>{a.bee}</b><span class:negative={a.pnl<0}>{money(a.pnl)}</span></button>{:else}<p>Ranking appears after recorded account evaluations.</p>{/each}<p>Ranked by current paper equity. Ties do not establish an edge.</p></section><section><div class="panel-title"><span>RESEARCH NURSERY</span><span>17 roles</span></div><div class="nursery">{#each beeCatalog.slice(3) as bee}<span title={bee.description}><i style={`background:${bee.color}`}></i>{bee.name}</span>{/each}</div><p>Research roles are not represented as trained trading strategies.</p></section></aside></div><section id="evidence" class="evidence"><div class="evidence-head"><div><span class="eyebrow">TRACE THE DECISION</span><h2>{selected} Bee · evidence journal</h2></div><div><select bind:value={selected} aria-label="Select Bee">{#each beeCatalog.slice(0,3) as bee}<option value={bee.id}>{bee.name}</option>{/each}</select><button class:chosen={view==='decisions'} onclick={()=>view='decisions'}>Decisions</button><button class:chosen={view==='fills'} onclick={()=>view='fills'}>Fills</button></div></div><div class="table"><table><thead><tr><th>Recorded</th><th>Action</th><th>{view==='fills'?'Execution price':'Model / source'}</th><th>{view==='fills'?'Notional / fee':'Reason'}</th></tr></thead><tbody>{#each [...(view==='fills'?active()?.fills??[]:active()?.decisions??[])].reverse() as e}<tr><td>{time(e.at)}</td><td><span class="action">{e.action??e.side}</span></td><td>{view==='fills'?money(e.price):e.model+' · '+e.source}</td><td>{view==='fills'?money(e.notional)+' / '+money(e.fee):e.reason}</td></tr>{:else}<tr><td colspan="4">No recorded {view} yet. A hold is a valid decision; trades are never fabricated.</td></tr>{/each}</tbody></table></div></section><div class="disclaimer">Live market observations · simulated capital · no guaranteed returns. History is bounded to 288 equity points and 24 decisions/fills per account. Bulk training artifacts stay outside Convex.</div></main>
<style>main{max-width:1900px;margin:auto;padding:26px;color:#edf0f6}header,nav,.heading,.bee-head,.panel-title,.evidence-head{display:flex;align-items:center;justify-content:space-between;gap:18px}header{padding-bottom:26px;border-bottom:1px solid #282d38}.brand{font-size:28px;font-weight:800;letter-spacing:-1px}.brand span,h1 span{color:#e7b64f}.brand small{display:block;color:#9ba6ba;font-size:8px;letter-spacing:3px;margin-top:6px}nav{font-size:12px;color:#b2bdd0}.mode{font-size:9px;color:#e9c56d;border:1px solid #b9923d44;padding:10px;border-radius:20px}i,.dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#68cfaa;margin-right:6px}.heading{margin:36px 0 28px}h1{font-size:clamp(30px,4vw,47px);letter-spacing:-1.8px;margin:10px 0}.eyebrow,.panel-title,small{font-size:9px;letter-spacing:1.3px;color:#96a4ba}p{font-size:12px;line-height:1.7;color:#97a4b9}button,select{border:1px solid #343b4a;border-radius:7px;padding:10px 13px;font-size:11px;background:#181d28;color:#d9e0ed}button:hover,a:hover{color:#f7d78e;border-color:#a78742}button:disabled{opacity:.5}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:24px}.metrics section,.side section,.evidence{background:#12151e;border:1px solid #2a2e3a;border-radius:12px;padding:20px}.metrics strong{display:block;font-size:26px;margin:10px 0}.metrics span{font-size:10px;color:#9aa7bd}.metrics .smaller{font-size:21px}.workspace{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:18px}.bee-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.bee-card{border:1px solid #32303e;border-top:3px solid var(--bee);border-radius:14px;background:linear-gradient(160deg,color-mix(in srgb,var(--bee) 7%,#15151e),#10121a 40%);padding:20px;min-width:0}.bee-head{gap:12px}.bee-head h2{font-size:20px;margin:0}.bee-head p{font-size:10px;margin:3px 0}.rank{font-size:25px;font-weight:750;margin-left:auto}.equity{display:block;font-size:clamp(25px,2.5vw,38px);letter-spacing:-1px;margin-top:26px}.return{color:#76d8ae;margin:8px 0 20px}.negative{color:#f48b9d!important}.state{padding:12px;border:1px solid #7d716440;background:#e4ba6010;border-radius:8px}.state strong{font-size:11px;color:var(--bee);letter-spacing:1px}.state span{display:block;font-size:11px;line-height:1.6;color:#b7bfce;margin-top:5px}.benched{border-color:#de607255;background:#de607212}.position{display:flex;flex-wrap:wrap;justify-content:space-between;gap:10px;margin-top:12px;padding:12px;background:#ffffff04;border:1px solid #ffffff0c;border-radius:8px;font-size:11px}.position small{width:100%;font-size:9px;letter-spacing:0}.chart{margin:30px 0}.chart-title,.axis{display:flex;justify-content:space-between;color:#8c9cb5;font-size:8px;gap:8px}.chart svg{width:100%;height:210px;overflow:visible}.axis{font-size:10px}.no-chart{height:210px;display:grid;place-content:center;text-align:center;font-size:11px;color:#748299;line-height:1.8}.call h3{font-size:17px;color:var(--bee);margin:10px 0}.call p{margin:0}.call>span{font-size:11px;color:#b5bfd0;line-height:1.7;display:block;margin-top:8px}.limits{margin-top:24px;display:grid;gap:8px;font-size:9px;color:#8e9cb2}.limits b{float:right;color:#d9deea}.limits progress{width:100%;height:5px;accent-color:var(--bee)}.bee-card footer{border-top:1px solid #2b2d38;display:flex;justify-content:space-between;gap:10px;margin-top:20px;padding-top:16px;font-size:8px;color:#95a2ba}.bee-card footer b{display:block;font-size:13px;color:#e9eef6;margin-top:5px}.bee-card footer button{font-size:9px;padding:7px}.side{display:grid;gap:14px;align-content:start}.side h2{font-size:18px;margin:15px 0}.side p{font-size:11px}.flow-grid{display:grid;grid-template-columns:55px 1fr;align-items:center;gap:15px;margin:25px 0}.core{font-size:35px;color:#bbaff0;text-align:center}.core small{display:block;font-size:8px;line-height:1.5}.flow-grid button{display:flex;align-items:center;width:100%;gap:10px;margin:8px 0;text-align:left;border-left:2px solid var(--bee)}.flow-grid b,.flow-grid small{display:block}.flow-grid small{font-size:9px;letter-spacing:0;margin-top:4px}.flow-grid .dot{margin-left:auto;background:var(--bee)}.keeper{border-color:#a46b2c!important;background:linear-gradient(120deg,#a2591314,#12151e)!important}.keeper a{display:block;padding:12px;border:1px solid #8b652c;border-radius:7px;font-size:10px;color:#edc176}.keeper small{display:block;line-height:1.8;letter-spacing:0;margin-top:12px}.leader{display:flex;width:100%;gap:12px;align-items:center;margin-top:10px;border:0;background:transparent;padding:8px 0}.leader b{text-transform:capitalize}.leader span:last-child{margin-left:auto;color:#78d9ac}.nursery{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}.nursery span{font-size:9px;background:#ffffff05;padding:6px;border-radius:5px}.nursery i{width:5px;height:5px}.evidence{margin-top:22px;scroll-margin-top:20px}.evidence h2{font-size:20px;text-transform:capitalize}.evidence-head>div:last-child{display:flex;gap:8px;flex-wrap:wrap}.chosen{color:#ebc66f;border-color:#a38645}.table{overflow:auto}table{width:100%;border-collapse:collapse;font-size:11px;text-align:left}td,th{padding:15px 10px;border-bottom:1px solid #282e3a}th{font-size:9px;color:#8b9bb4;font-weight:500}.action{color:#e2bf6f;text-transform:uppercase}.disclaimer{font-size:10px;line-height:1.8;color:#7e8da4;margin:22px 0}aside[role=alert]{color:#ef9caa;padding:16px;border:1px solid #914757;border-radius:8px;margin-bottom:16px}@media(min-width:1700px){.chart svg,.no-chart{height:300px}}@media(max-width:1200px){.workspace{grid-template-columns:1fr}.side{grid-template-columns:repeat(2,minmax(0,1fr))}.bee-card{padding:16px}.bee-head h2{font-size:17px}}@media(max-width:760px){main{padding:16px}header{flex-wrap:wrap}.mode{font-size:8px}nav{gap:15px;font-size:10px}.metrics{grid-template-columns:1fr 1fr}.metrics section{padding:14px}.metrics strong{font-size:23px}.bee-grid,.side{grid-template-columns:1fr}.heading{align-items:flex-start}.heading button{white-space:nowrap;font-size:9px}.eyebrow{font-size:7px}h1{font-size:31px}.chart svg{height:230px}.evidence-head{align-items:flex-start;flex-direction:column}.equity{font-size:38px}.bee-head h2{font-size:21px}td{min-width:110px}}@media(prefers-reduced-motion:no-preference){.bee-card{animation:arrive .4s ease-out both}.bee-card:nth-child(2){animation-delay:.08s}.bee-card:nth-child(3){animation-delay:.16s}button,a{transition:color .15s,border-color .15s,background .15s}@keyframes arrive{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}}</style>
